#!/usr/bin/env python3
"""Extract the offline pilot into a new directory. No network calls."""
import argparse, base64, hashlib, io, zipfile
from pathlib import Path
PAYLOAD = ''
SHA256 = '8b4be0dd3b6c02039267913bafa32b9b84f3752651e9a36b1e91d6c8f806022b'

def main():
 p=argparse.ArgumentParser(description=__doc__)
 p.add_argument('--out', default='pilot-starter')
 a=p.parse_args(); target=Path(a.out)
 if target.exists(): p.exit(2,'Output directory already exists; choose a new --out path.\n')
 raw=base64.b64decode(PAYLOAD)
 if hashlib.sha256(raw).hexdigest()!=SHA256:p.exit(2,'Archive checksum mismatch.\n')
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  for item in z.infolist():
   if Path(item.filename).is_absolute() or '..' in Path(item.filename).parts:
    p.exit(2,'Unsafe archive path.\n')
  target.mkdir(parents=True);z.extractall(target)
 print('Extracted to',target)
 print('Next: cd',target)
 print('Then: python -m unittest discover -s tests -v')
 print('Read README.md before collecting real outputs. No model calls made.')
if __name__=='__main__':main()
